from __future__ import annotations

from collections.abc import Mapping
from typing import Any, Final

from repomod.dependencies.graph import Graph
from repomod.dependencies.jsdata import dump_js
from repomod.dependencies.model import ERROR_COVERAGE_KINDS, Relation

SCHEMA_VERSION: Final = 1

_BANNER: Final = (
    "/* atlas.js — generated by `repomod deps render` from the filtered fleet\n"
    "   dependency inventory; do not edit, and do not load it from the network. */\n"
    "window.DEPS_ATLAS = "
)

_STATE_ORDER: Final = ("complete", "partial", "failed", "unavailable")


def ecosystems(graph: Graph) -> list[str]:
    return sorted(
        {item.ecosystem.value for item in graph.components.values()}
        | {project.ecosystem.value for project in graph.projects.values()}
    )


def build(graph: Graph, *, hidden: frozenset[str] = frozenset()) -> str:
    return _BANNER + dump_js(_payload(graph, hidden=hidden)) + ";\n"


def _payload(graph: Graph, *, hidden: frozenset[str]) -> Mapping[str, Any]:
    ecosystem_names = ecosystems(graph)
    ecosystem_index = {value: index for index, value in enumerate(ecosystem_names)}
    source_kinds = sorted(
        {item.source_kind.value for item in graph.instances.values()}
        | {edge.edge.source_kind.value for edge in graph.edges}
    )
    source_index = {value: index for index, value in enumerate(source_kinds)}
    resolutions = sorted({edge.edge.resolution.value for edge in graph.edges})
    resolution_index = {value: index for index, value in enumerate(resolutions)}
    scopes = sorted({edge.edge.scope.value for edge in graph.edges})
    scope_index = {value: index for index, value in enumerate(scopes)}
    relations = [Relation.DIRECT.value, Relation.TRANSITIVE.value]
    relation_index = {value: index for index, value in enumerate(relations)}

    strings: list[str] = []
    string_index: dict[str, int] = {}

    def intern(value: str | None) -> int:
        if value is None:
            return -1
        index = string_index.get(value)
        if index is None:
            index = len(strings)
            string_index[value] = index
            strings.append(value)
        return index

    components: list[list[Any]] = []
    component_index: dict[str, int] = {}
    for purl, component in sorted(graph.components.items()):
        component_index[purl] = len(components)
        components.append(
            [
                purl,
                ecosystem_index[component.ecosystem.value],
                component.name,
                component.display_name,
            ]
        )

    instances: list[list[Any]] = []
    instance_index: dict[str, int] = {}
    for instance_id, instance in sorted(graph.instances.items()):
        instance_index[instance_id] = len(instances)
        instances.append(
            [
                instance.id,
                component_index[instance.component],
                instance.version,
                source_index[instance.source_kind.value],
                1 if instance.first_party else 0,
                len(graph.instance_repositories.get(instance.id, ())),
            ]
        )

    repositories: list[dict[str, Any]] = []
    totals = dict.fromkeys(_STATE_ORDER, 0)
    direct_total = 0
    transitive_total = 0
    for name, data in sorted(graph.repositories.items()):
        repo_projects = sorted(
            data.projects, key=lambda project: (project.ecosystem.value, project.id)
        )
        repo_project_index = {project.id: index for index, project in enumerate(repo_projects)}
        aggregate: dict[int, list[int]] = {}
        edges: list[list[int]] = []
        direct = 0
        transitive = 0
        for edge in data.edges:
            if edge.relation is Relation.DIRECT:
                direct += 1
            else:
                transitive += 1
            from_kind, from_ref = _endpoint(edge.from_id, repo_project_index, instance_index)
            to_kind, to_ref = _endpoint(edge.to_id, repo_project_index, instance_index)
            target = graph.instances.get(edge.to_id)
            if target is not None:
                component = graph.components.get(target.component)
                if component is not None:
                    bucket = aggregate.setdefault(ecosystem_index[component.ecosystem.value], [0, 0])
                    bucket[0 if edge.relation is Relation.DIRECT else 1] += 1
            edges.append(
                [
                    from_kind,
                    from_ref,
                    to_kind,
                    to_ref,
                    relation_index[edge.relation.value],
                    scope_index[edge.scope.value],
                    1 if edge.optional else 0,
                    resolution_index[edge.resolution.value],
                    source_index[edge.source_kind.value],
                    intern(edge.constraint),
                    intern(edge.resolved_version),
                    intern(edge.condition),
                ]
            )
        error_count = sum(1 for issue in data.issues if issue.kind in ERROR_COVERAGE_KINDS)
        state = data.state.value
        totals[state] = totals.get(state, 0) + 1
        direct_total += direct
        transitive_total += transitive
        repositories.append(
            {
                "n": name,
                "s": state,
                "t": sorted(graph.tags.get(name, data.tags)),
                "r": error_count,
                "c": len(data.issues),
                "d": direct,
                "x": transitive,
                "p": [
                    [project.id, ecosystem_index[project.ecosystem.value], project.directory]
                    for project in repo_projects
                ],
                "a": [
                    [eco, pair[0], pair[1]]
                    for eco, pair in sorted(aggregate.items())
                    if pair[0] or pair[1]
                ],
                "e": edges,
            }
        )

    summary = {
        "repositories": len(graph.repositories),
        "hidden": len(hidden),
        "projects": len(graph.projects),
        "instances": len(graph.instances),
        "components": len(graph.components),
        "edges": len(graph.edges),
        "direct": direct_total,
        "transitive": transitive_total,
        "states": totals,
    }

    return {
        "v": SCHEMA_VERSION,
        "summary": summary,
        "ecosystems": ecosystem_names,
        "scopes": scopes,
        "relations": relations,
        "resolutions": resolutions,
        "source_kinds": source_kinds,
        "components": components,
        "instances": instances,
        "strings": strings,
        "repositories": repositories,
    }


def _endpoint(
    node_id: str,
    repo_project_index: Mapping[str, int],
    instance_index: Mapping[str, int],
) -> tuple[int, int]:
    project = repo_project_index.get(node_id)
    if project is not None:
        return 0, project
    instance = instance_index.get(node_id)
    if instance is None:
        raise ValueError(f"edge references unknown node: {node_id!r}")
    return 1, instance
